-- ============================================================================
-- seed-chuokai-zg-snapshot.sql
--   Snapshot SEED của account `chuokai_zg` + toàn bộ dữ liệu liên quan
--   (JA / 管理支店 / 販売店 / 単価 / 独giả t_dokusya / lịch sử t_dokusya_rireki).
--
-- Mục đích : chuyển sang DB MỚI (đã chạy migration) hoặc reset DB hiện tại mà
--            vẫn có nguyên bộ dữ liệu độc giả của chuokai_zg để test
--            (SCR-020/021 口座振替, SCR-026 名簿, SCR-028/029 増減連絡票/通知…).
--
-- Đặc điểm :
--   • IDEMPOTENT — xóa đúng graph chuokai_zg (theo ja_code='JAZG9001' +
--     login_id='chuokai_zg') rồi chèn lại. Chạy nhiều lần đều ra cùng kết quả.
--   • GIỮ NGUYÊN ID gốc (ja_id=108, account_id=29, dokusya 172–176, …) để
--     khớp các script verify/test khác. Trên DB mới các ID này còn trống.
--   • Tự fix sequence sau khi chèn (setval = MAX(id)).
--   • Snapshot phản ánh TRẠNG THÁI HIỆN TẠI của DB dev (gồm cả thay đổi địa chỉ
--     dokusya 176). Sinh tự động từ live DB — KHÔNG sửa tay phần INSERT.
--
-- Phụ thuộc (phải có sẵn, do migration seed): m_todofuken (code 13),
--   m_roles (role_id=3 CHUOKAI), m_code, m_permissions…
--
-- Chạy:
--   docker exec -i agrinews-postgres-1 psql -U postgres -d <db> \
--     -v ON_ERROR_STOP=1 < docs/zougen-028-029-and-validate-scr-016/seed-chuokai-zg-snapshot.sql
--
-- Login: chuokai_zg / admin@1234567   (password_hash giữ nguyên từ snapshot)
-- ============================================================================

BEGIN;

-- ── 1) CLEANUP graph cũ (children → parent, NULL-safe) ──────────────────────
DELETE FROM t_dokusya_rireki WHERE ja_id IN (SELECT ja_id FROM m_ja WHERE ja_code='JAZG9001');
DELETE FROM t_dokusya        WHERE ja_id IN (SELECT ja_id FROM m_ja WHERE ja_code='JAZG9001');
DELETE FROM t_mfa_otp   WHERE account_id IN (SELECT account_id FROM m_account WHERE login_id='chuokai_zg');
DELETE FROM t_log       WHERE account_id IN (SELECT account_id FROM m_account WHERE login_id='chuokai_zg');
DELETE FROM t_login_log WHERE account_id IN (SELECT account_id FROM m_account WHERE login_id='chuokai_zg');
DELETE FROM m_account   WHERE login_id='chuokai_zg';
DELETE FROM m_hanbaiten WHERE ja_id IN (SELECT ja_id FROM m_ja WHERE ja_code='JAZG9001');
DELETE FROM m_tanka     WHERE ja_id IN (SELECT ja_id FROM m_ja WHERE ja_code='JAZG9001');
DELETE FROM m_shiten    WHERE ja_id IN (SELECT ja_id FROM m_ja WHERE ja_code='JAZG9001');
DELETE FROM m_kanri_shiten WHERE ja_id IN (SELECT ja_id FROM m_ja WHERE ja_code='JAZG9001');
DELETE FROM m_ja        WHERE ja_code='JAZG9001';

-- ── 2) INSERT snapshot (sinh tự động, giữ nguyên ID) ────────────────────────
