INSERT INTO m_ja (ja_id,ja_code,ja_name,ja_name_kana,todofuken_code,yubin_no,address,tel,fax,email,tanto_busho,tanto_name,jastem_itakusha_code,jastem_itakusha_name,jastem_ja_code,jastem_ja_name,chuokai_flg,zei_kubun,biko,deleted_at,created_at,created_by,updated_at,updated_by) VALUES ('108', 'JAZG9001', '増減検証JA', 'ｿﾞｳｹﾞﾝｹﾝｼｮｳｼﾞｪｲｴｰ', '13', '1000001', '東京都千代田区1-1-1', '03-0000-1111', '03-0000-0002', '', '', '', '', '', '', '', 'false', '1', '', NULL, '2026-06-21 19:48:37.608732+09', 'SEED_ZG', '2026-06-21 19:48:37.608732+09', 'SEED_ZG');

